/**
 * Points every issue that carries `sourceLabelId` at `targetLabelId`, then
 * deletes the source label. Issues that already carry the target keep a single
 * join row — the overlapping source row is removed before the retarget so the
 * `(issue_id, label_id)` unique index does not reject the update.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  if (sourceLabelId === targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const db = getDb();
  return db.transaction((tx) => {
    const source = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .get();
    const target = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, targetLabelId)))
      .get();

    if (!source) throw new Error(`Label ${sourceLabelId} not found`);
    if (!target) throw new Error(`Label ${targetLabelId} not found`);

    const sourceIssueRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();
    const issuesRelabelled = new Set(sourceIssueRows.map((row) => row.issueId)).size;

    const targetIssueRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, targetLabelId),
        ),
      )
      .all();
    const targetIssueIds = new Set(targetIssueRows.map((row) => row.issueId));
    const overlapping = [
      ...new Set(
        sourceIssueRows
          .map((row) => row.issueId)
          .filter((issueId) => targetIssueIds.has(issueId)),
      ),
    ];

    if (overlapping.length > 0) {
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
            inArray(issueLabels.issueId, overlapping),
          ),
        )
        .run();
    }

    tx.update(issueLabels)
      .set({ labelId: targetLabelId })
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return { label: toLabel(target), issuesRelabelled };
  });
}

