  return [...labelIds].sort();
}

async function makeLabel(tenant: Tenant, name: string) {
  return labelService.createLabel(tenant.actors.admin, {
    orgId: tenant.org.id,
    name,
    color: "#112233",
    description: `${name} desc`,
  });
}

async function makeIssue(
  tenant: Tenant,
  title: string,
  labelIds: readonly LabelId[],
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    { ...issueInput(tenant.org.id, tenant.project.id, { title }), labelIds: [...labelIds] },
    tenant.userIds.admin,
    number,
  );
}

describe("mergeLabels", () => {
  it("rejects identical ids in the schema", () => {
    const orgId = "01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId;
    const same = mergeLabelsSchema.safeParse({
      orgId,
      sourceLabelId: SOURCE,
      targetLabelId: SOURCE,
    });
    expect(same.success).toBe(false);
    const distinct = mergeLabelsSchema.safeParse({
      orgId,
      sourceLabelId: SOURCE,
      targetLabelId: TARGET,
    });
    expect(distinct.success).toBe(true);
  });

  it("rejects a different organization and an actor who cannot delete labels", async () => {
    const source = await makeLabel(north, "scope-source");
    const target = await makeLabel(north, "scope-target");

    await expect(
      labelService.mergeLabels(acme.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      labelService.mergeLabels(north.actors.member, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(await labelRepo.findLabelById(north.org.id, source.id)).not.toBeNull();
    expect(await labelRepo.findLabelById(north.org.id, target.id)).not.toBeNull();
  });

  it("rejects a missing label and a label that belongs to another organization", async () => {
    const source = await makeLabel(north, "missing-source");
    const foreign = await makeLabel(acme, "foreign-target");
    const before = await labelRepo.listLabels(acme.org.id);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: SOURCE,
        targetLabelId: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await labelRepo.findLabelById(north.org.id, source.id)).not.toBeNull();
    expect(await labelRepo.listLabels(acme.org.id)).toEqual(before);
  });

  it("rejects merging a label into itself and leaves it in place", async () => {
    const label = await makeLabel(north, "same-label");
    const issue = await makeIssue(north, "keeps same label", [label.id]);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: label.id,
        targetLabelId: label.id,
      }),
    ).rejects.toThrow(/itself/);

    expect(await labelRepo.findLabelById(north.org.id, label.id)).not.toBeNull();
    const reloaded = await issueRepo.findIssueById(north.org.id, issue.id);
    expect(idsOf(reloaded?.labelIds ?? [])).toEqual([label.id]);
  });

  it("retargets every issue, including archived ones and ones that already have the target", async () => {
    const source = await makeLabel(north, "defect");
    const target = await makeLabel(north, "bug");
    const other = await makeLabel(north, "docs");
    const untouchedTarget = { ...target };

    const onlySource = await makeIssue(north, "only source", [source.id]);
    const both = await makeIssue(north, "both labels", [source.id, target.id]);
    const sourceAndOther = await makeIssue(north, "source and other", [source.id, other.id]);
    const onlyOther = await makeIssue(north, "only other", [other.id]);
    const onlyTarget = await makeIssue(north, "only target", [target.id]);
    const archived = await makeIssue(north, "archived source", [source.id, other.id]);
    await issueRepo.archiveIssue(north.org.id, archived.id);
    const none = await makeIssue(north, "no labels", []);

    const targetRowBefore = getDb()
      .select()
      .from(labels)
      .where(and(eq(labels.orgId, north.org.id), eq(labels.id, target.id)))
      .get();

    const result = await labelService.mergeLabels(north.actors.owner, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });

    expect(result.issuesRelabelled).toBe(4);
    expect(result.label).toEqual(untouchedTarget);

    const targetRowAfter = getDb()
      .select()
      .from(labels)
      .where(and(eq(labels.orgId, north.org.id), eq(labels.id, target.id)))
      .get();
    expect(targetRowAfter).toEqual(targetRowBefore);

    expect(await labelRepo.findLabelById(north.org.id, source.id)).toBeNull();

    const load = async (id: (typeof onlySource)["id"]) =>
      idsOf((await issueRepo.findIssueById(north.org.id, id))?.labelIds ?? []);

    expect(await load(onlySource.id)).toEqual(idsOf([target.id]));
    expect(await load(both.id)).toEqual(idsOf([target.id]));
    expect(await load(sourceAndOther.id)).toEqual(idsOf([target.id, other.id]));
    expect(await load(onlyOther.id)).toEqual(idsOf([other.id]));
    expect(await load(onlyTarget.id)).toEqual(idsOf([target.id]));
    expect(await load(archived.id)).toEqual(idsOf([target.id, other.id]));
    expect(await load(none.id)).toEqual([]);

    const sourceJoins = getDb()
      .select()
      .from(issueLabels)
      .where(eq(issueLabels.labelId, source.id))
      .all();
    expect(sourceJoins).toEqual([]);
  });

  it("does not relabel issues in another organization", async () => {
    const source = await makeLabel(north, "north-defect");
    const target = await makeLabel(north, "north-bug");
    const acmeSource = await makeLabel(acme, "acme-defect");
    const acmeIssue = await makeIssue(acme, "acme issue", [acmeSource.id]);
    const northIssue = await makeIssue(north, "north issue", [source.id]);

    const result = await labelService.mergeLabels(north.actors.admin, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });

    expect(result.issuesRelabelled).toBe(1);
    const northReloaded = await issueRepo.findIssueById(north.org.id, northIssue.id);
    expect(idsOf(northReloaded?.labelIds ?? [])).toEqual([target.id]);
    const acmeReloaded = await issueRepo.findIssueById(acme.org.id, acmeIssue.id);
    expect(idsOf(acmeReloaded?.labelIds ?? [])).toEqual([acmeSource.id]);
    expect(await labelRepo.findLabelById(acme.org.id, acmeSource.id)).not.toBeNull();
  });

  it("counts zero when the source is unused and still removes it", async () => {
    const source = await makeLabel(north, "unused-source");
    const target = await makeLabel(north, "unused-target");
    const result = await labelService.mergeLabels(north.actors.admin, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });
    expect(result.issuesRelabelled).toBe(0);
    expect(result.label.id).toBe(target.id);
    expect(await labelRepo.findLabelById(north.org.id, source.id)).toBeNull();
  });

  it("rejects a direct call that skipped the schema when the ids match", async () => {
    const label = await makeLabel(north, "direct-same");
    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: label.id,
        targetLabelId: label.id,
      }),
    ).rejects.toThrow();
    expect(await labelRepo.findLabelById(north.org.id, label.id)).not.toBeNull();
  });
});
